('poster-sun-moon','poster','اللام الشمسية واللام القمرية','ملصق يفرّق بين الحروف الشمسية والقمرية مع القاعدة ومثال لكل نوع. أربعة عشر حرفًا في كل مجموعة.',array['g1','g2','g3']::text[],'اللغة العربية','قواعد اللغة','portrait',1,'images/media/poster-sun-moon/thumb.webp','files/media/poster-sun-moon.pdf','files/media/poster-sun-moon-bw.pdf',array['images/media/poster-sun-moon/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. محتوى وتصميم أصليان من إعداد زاد؛ الرسومات من مكتبة زاد الكرتونية. لم يُراجَع من جهة تعليمية رسمية.','published',15),
('pr-ruler','printable','مسطرة ورقية للقص (١٥ سم)','مسطرتان بطول ١٥ سنتيمترًا بتدريج دقيق (مليمتر وسنتيمتر) للقص والتلوين، مع خط اختبار طوله ١٠ سم للتأكد من الطباعة بالحجم الحقيقي.',array['g1','g2','g3']::text[],'الرياضيات','القياس','portrait',1,'images/media/pr-ruler/thumb.webp','files/media/pr-ruler.pdf','files/media/pr-ruler-bw.pdf',array['images/media/pr-ruler/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد. اطبع بحجم ١٠٠٪ على ورق A4 دون تصغير. لم تُراجَع من جهة تعليمية رسمية.','published',1),
('pr-paper-clock','printable','ساعة ورقية للقص والتركيب','وجه ساعة كبير بالأرقام والدقائق مع عقربين للقص والتثبيت بدبوس، لتدريب الطفل على قراءة الوقت.',array['a6','g1','g2']::text[],'الرياضيات','الزمن','portrait',1,'images/media/pr-paper-clock/thumb.webp','files/media/pr-paper-clock.pdf','files/media/pr-paper-clock-bw.pdf',array['images/media/pr-paper-clock/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد. اطبع بحجم ١٠٠٪ على ورق A4 دون تصغير. لم تُراجَع من جهة تعليمية رسمية.','published',2),
('pr-routine-chart','printable','جدول روتيني اليومي','جدول أسبوعي لمتابعة ست عادات يومية للطفل: الاستيقاظ المبكر والفطور ونظافة الأسنان وترتيب الحقيبة والقراءة والنوم المبكر، مع خانات للتلوين أو وضع علامة.',array['a4','a5','a6','g1','g2','g3']::text[],'المهارات الحياتية','الروتين اليومي','portrait',1,'images/media/pr-routine-chart/thumb.webp','files/media/pr-routine-chart.pdf','files/media/pr-routine-chart-bw.pdf',array['images/media/pr-routine-chart/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد. اطبع بحجم ١٠٠٪ على ورق A4 دون تصغير. لم تُراجَع من جهة تعليمية رسمية.','published',3),
('sl-five-senses','slides','عرض: حواسي الخمس','عرض تقديمي من تسع شرائح عن الحواس الخمس: العضو المسؤول عن كل حاسة وماذا نعرف بها، مع نشاط تطبيقي وخلاصة.',array['a6','g1','g2']::text[],'العلوم','جسم الإنسان','landscape',9,'images/media/sl-five-senses/thumb.webp','files/media/sl-five-senses.pdf','files/media/sl-five-senses-bw.pdf',array['images/media/sl-five-senses/p01.webp','images/media/sl-five-senses/p02.webp','images/media/sl-five-senses/p03.webp','images/media/sl-five-senses/p04.webp','images/media/sl-five-senses/p05.webp','images/media/sl-five-senses/p06.webp','images/media/sl-five-senses/p07.webp','images/media/sl-five-senses/p08.webp','images/media/sl-five-senses/p09.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. عرض تقديمي أصلي من إعداد زاد، بلا نسب إلى كتاب أو منهج محدد، ولم يُراجَع من جهة تعليمية رسمية.','published',1),
('sl-plant-parts','slides','عرض: أجزاء النبات','عرض تقديمي من تسع شرائح عن أجزاء النبات ووظائفها: الجذر والساق والأوراق والزهرة والبذرة، مع أسئلة مراجعة وخلاصة.',array['g1','g2','g3']::text[],'العلوم','النبات','landscape',9,'images/media/sl-plant-parts/thumb.webp','files/media/sl-plant-parts.pdf','files/media/sl-plant-parts-bw.pdf',array['images/media/sl-plant-parts/p01.webp','images/media/sl-plant-parts/p02.webp','images/media/sl-plant-parts/p03.webp','images/media/sl-plant-parts/p04.webp','images/media/sl-plant-parts/p05.webp','images/media/sl-plant-parts/p06.webp','images/media/sl-plant-parts/p07.webp','images/media/sl-plant-parts/p08.webp','images/media/sl-plant-parts/p09.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. عرض تقديمي أصلي من إعداد زاد، بلا نسب إلى كتاب أو منهج محدد، ولم يُراجَع من جهة تعليمية رسمية.','published',2),
